"use server";

import { prisma } from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import bcrypt from "bcryptjs";
import { getAuthUser } from "@/lib/auth";

export async function updateProfile(name: string, email: string, department?: string, phone?: string) {
    try {
        const user = await getAuthUser();
        if (!user) return { error: "Unauthorized" };

        // Check email uniqueness (exclude current user)
        if (email !== user.email) {
            const existing = await prisma.user.findUnique({ where: { email } });
            if (existing) return { error: "อีเมลนี้ถูกใช้งานแล้ว" };
        }

        await prisma.user.update({
            where: { id: user.id },
            data: {
                name,
                email,
                department: department || null,
                phone: phone || null,
            }
        });
        revalidatePath("/settings");
        return { success: true };
    } catch (err: unknown) {
        console.error("updateProfile error:", err);
        return { error: "เกิดข้อผิดพลาดในการบันทึกข้อมูล" };
    }
}

export async function changePassword(currentPassword: string, newPassword: string) {
    const authUser = await getAuthUser();
    if (!authUser) throw new Error("Unauthorized");

    // Fetch user with password hash
    const user = await prisma.user.findUnique({ where: { id: authUser.id } });
    if (!user) throw new Error("User not found");

    // Verify current password
    let isCurrentValid = false;
    if (user.password.startsWith("$2a$") || user.password.startsWith("$2b$")) {
        isCurrentValid = await bcrypt.compare(currentPassword, user.password);
    } else {
        // Legacy plaintext comparison
        isCurrentValid = user.password === currentPassword;
    }

    if (!isCurrentValid) {
        return { error: "รหัสผ่านปัจจุบันไม่ถูกต้อง" };
    }

    // Validate new password
    if (newPassword.length < 6) {
        return { error: "รหัสผ่านใหม่ต้องมีอย่างน้อย 6 ตัวอักษร" };
    }

    // Hash and save
    const hashedPassword = await bcrypt.hash(newPassword, 10);
    await prisma.user.update({
        where: { id: authUser.id },
        data: { password: hashedPassword }
    });

    return { success: true };
}

import { supabase } from "@/lib/supabase";

export async function uploadAvatar(formData: FormData) {
    try {
        const user = await getAuthUser();
        if (!user) return { error: "Unauthorized" };

        const file = formData.get("file") as File;
        if (!file) return { error: "No file uploaded" };

        // Check if it's an image
        if (!file.type.startsWith("image/")) {
            return { error: "File is not an image" };
        }

        const bytes = await file.arrayBuffer();
        const buffer = Buffer.from(bytes);

        // Generate unique filename
        const ext = file.name.split(".").pop();
        const uniqueId = `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
        const fileName = `${user.id}-${uniqueId}.${ext}`;

        // Upload to Supabase Storage
        const { data, error } = await supabase.storage
            .from('avatars')
            .upload(fileName, buffer, {
                contentType: file.type,
                upsert: true
            });

        if (error) {
            console.error("Supabase storage error:", error);
            return { error: "อัปโหลดรูปล้มเหลว ตรวจสอบว่าสร้าง Bucket 'avatars' แล้วหรือยัง" };
        }

        // Get public URL
        const { data: publicUrlData } = supabase.storage
            .from('avatars')
            .getPublicUrl(fileName);

        const avatarUrl = publicUrlData.publicUrl;

        // Update user
        await prisma.user.update({
            where: { id: user.id },
            data: { avatarUrl }
        });

        revalidatePath("/settings");
        return { avatarUrl };
    } catch (err: unknown) {
        console.error("uploadAvatar error:", err);
        return { error: "เกิดข้อผิดพลาดในการอัปโหลดรูปภาพ" };
    }
}

"use client";

import { useState, useTransition } from "react";
import { Check, X, Loader2 } from "lucide-react";

type Props = {
    userId: string;
    userName: string;
};

async function approveUser(userId: string) {
    const res = await fetch("/api/admin/approve", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId, action: "approve" }),
    });
    return res.json();
}

async function rejectUser(userId: string) {
    const res = await fetch("/api/admin/approve", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId, action: "reject" }),
    });
    return res.json();
}

export default function ApprovalActions({ userId, userName }: Props) {
    const [isPending, startTransition] = useTransition();
    const [done, setDone] = useState<"approved" | "rejected" | null>(null);
    const [confirmReject, setConfirmReject] = useState(false);

    const handleApprove = () => {
        startTransition(async () => {
            await approveUser(userId);
            setDone("approved");
        });
    };

    const handleReject = () => {
        if (!confirmReject) {
            setConfirmReject(true);
            setTimeout(() => setConfirmReject(false), 3000);
            return;
        }
        startTransition(async () => {
            await rejectUser(userId);
            setDone("rejected");
        });
    };

    if (done === "approved") {
        return (
            <span className="text-xs font-bold text-emerald-600 bg-emerald-50 px-3 py-1.5 rounded-xl border border-emerald-200">
                ✓ อนุมัติแล้ว
            </span>
        );
    }
    if (done === "rejected") {
        return (
            <span className="text-xs font-bold text-rose-600 bg-rose-50 px-3 py-1.5 rounded-xl border border-rose-200">
                ✗ ปฏิเสธแล้ว
            </span>
        );
    }

    return (
        <div className="flex items-center gap-2 shrink-0">
            <button
                onClick={handleApprove}
                disabled={isPending}
                className="flex items-center gap-1.5 px-4 py-2 text-xs font-bold text-emerald-700 bg-emerald-50 border border-emerald-200 hover:bg-emerald-100 rounded-xl transition-all disabled:opacity-60 shadow-2xs"
            >
                {isPending ? <Loader2 size={13} className="animate-spin" /> : <Check size={13} />}
                อนุมัติ
            </button>
            <button
                onClick={handleReject}
                disabled={isPending}
                className={`flex items-center gap-1.5 px-4 py-2 text-xs font-bold rounded-xl border transition-all disabled:opacity-60 shadow-2xs ${
                    confirmReject
                        ? "text-white bg-rose-600 border-rose-700 hover:bg-rose-700 animate-pulse"
                        : "text-rose-600 bg-rose-50 border-rose-200 hover:bg-rose-100"
                }`}
            >
                <X size={13} />
                {confirmReject ? "ยืนยันปฏิเสธ?" : "ปฏิเสธ"}
            </button>
        </div>
    );
}

"use client";

import { useState, useTransition } from "react";
import { Users, Shield, KeyRound, UserX, UserCheck, Plus, X, Save } from "lucide-react";
import { updateUserRole, toggleUserActive, adminResetPassword, adminCreateUser } from "@/app/actions/admin";

type User = {
    id: string;
    name: string;
    email: string;
    role: string;
    isActive: boolean;
    createdAt: Date;
    _count: { projectsOwned: number; projectsAssigned: number };
};

const ROLES = ["ADMIN", "PM", "DEV"];

const roleColors: Record<string, string> = {
    ADMIN: "bg-rose-50 text-rose-700 border-rose-200",
    PM: "bg-emerald-50 text-emerald-700 border-emerald-200",
    DEV: "bg-emerald-50 text-emerald-700 border-emerald-200",
};

export default function UsersTable({ users: initial }: { users: User[] }) {
    const [users, setUsers] = useState(initial);
    const [isPending, startTransition] = useTransition();
    const [resetTarget, setResetTarget] = useState<string | null>(null);
    const [newPassword, setNewPassword] = useState("");
    const [showCreate, setShowCreate] = useState(false);
    const [createForm, setCreateForm] = useState({ name: "", email: "", password: "", role: "DEV" });
    const [feedback, setFeedback] = useState("");

    const showFeedback = (msg: string) => {
        setFeedback(msg);
        setTimeout(() => setFeedback(""), 3000);
    };

    const handleRoleChange = (userId: string, role: string) => {
        startTransition(async () => {
            await updateUserRole(userId, role);
            setUsers(u => u.map(x => x.id === userId ? { ...x, role } : x));
            showFeedback("Role updated");
        });
    };

    const handleToggleActive = (userId: string, isActive: boolean) => {
        startTransition(async () => {
            await toggleUserActive(userId, !isActive);
            setUsers(u => u.map(x => x.id === userId ? { ...x, isActive: !isActive } : x));
        });
    };

    const handleResetPassword = () => {
        if (!resetTarget || !newPassword) return;
        startTransition(async () => {
            await adminResetPassword(resetTarget, newPassword);
            setResetTarget(null);
            setNewPassword("");
            showFeedback("Password reset successfully");
        });
    };

    const handleCreateUser = () => {
        startTransition(async () => {
            const res = await adminCreateUser(createForm.name, createForm.email, createForm.password, createForm.role);
            const response = res as { error?: string };
            if (response?.error) {
                showFeedback(response.error);
            } else {
                setShowCreate(false);
                setCreateForm({ name: "", email: "", password: "", role: "DEV" });
                showFeedback("User created!");
                window.location.reload();
            }
        });
    };

    return (
        <div className="space-y-4">
            {feedback && (
                <div className="p-3 bg-emerald-50 border border-emerald-200 text-emerald-700 text-xs font-bold rounded-xl">{feedback}</div>
            )}

            <div className="flex justify-end">
                <button
                    onClick={() => setShowCreate(true)}
                    className="flex items-center gap-1.5 bg-gradient-to-r from-emerald-600 to-green-600 text-white text-xs font-bold px-4 py-2.5 rounded-xl shadow-md shadow-emerald-500/20 hover:scale-105 transition-all"
                >
                    <Plus size={15} /> Create User
                </button>
            </div>

            <div className="overflow-x-auto border border-slate-200/80 rounded-2xl">
                <table className="w-full text-left border-collapse text-sm">
                    <thead>
                        <tr className="bg-slate-50/80 text-slate-500 border-b border-slate-200/80 text-xs font-extrabold uppercase tracking-wider">
                            <th className="px-5 py-3.5">User</th>
                            <th className="px-5 py-3.5">Role</th>
                            <th className="px-5 py-3.5 text-center">Projects</th>
                            <th className="px-5 py-3.5 text-center">Status</th>
                            <th className="px-5 py-3.5 text-center">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {users.map(u => (
                            <tr key={u.id} className={`hover:bg-slate-50/60 transition-colors ${!u.isActive ? "opacity-50" : ""}`}>
                                <td className="px-5 py-4">
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 rounded-xl bg-gradient-to-br from-emerald-500 to-green-600 flex items-center justify-center text-white font-extrabold text-xs shrink-0">
                                            {u.name.charAt(0).toUpperCase()}
                                        </div>
                                        <div>
                                            <div className="font-bold text-slate-800 text-sm">{u.name}</div>
                                            <div className="text-xs text-slate-500">{u.email}</div>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-5 py-4">
                                    <select
                                        value={u.role}
                                        onChange={(e) => handleRoleChange(u.id, e.target.value)}
                                        disabled={isPending}
                                        className={`text-xs font-extrabold px-2.5 py-1.5 border rounded-xl outline-none focus:ring-2 focus:ring-emerald-400 cursor-pointer ${roleColors[u.role] || "bg-slate-50 text-slate-600 border-slate-200"}`}
                                    >
                                        {ROLES.map(r => <option key={r} value={r}>{r}</option>)}
                                    </select>
                                </td>
                                <td className="px-5 py-4 text-center">
                                    <div className="text-xs font-bold text-slate-700">
                                        <span className="text-emerald-600">{u._count.projectsOwned}</span> PM
                                        <span className="text-slate-400 mx-1">·</span>
                                        <span className="text-emerald-600">{u._count.projectsAssigned}</span> DEV
                                    </div>
                                </td>
                                <td className="px-5 py-4 text-center">
                                    <button
                                        onClick={() => handleToggleActive(u.id, u.isActive)}
                                        disabled={isPending}
                                        className={`flex items-center gap-1 mx-auto text-[11px] font-bold px-3 py-1 rounded-xl border transition-all ${u.isActive ? "bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100" : "bg-slate-100 text-slate-500 border-slate-200 hover:bg-slate-200"}`}
                                    >
                                        {u.isActive ? <><UserCheck size={12} /> Active</> : <><UserX size={12} /> Inactive</>}
                                    </button>
                                </td>
                                <td className="px-5 py-4 text-center">
                                    <button
                                        onClick={() => setResetTarget(u.id)}
                                        className="flex items-center gap-1 mx-auto text-[11px] font-bold px-3 py-1 rounded-xl bg-amber-50 border border-amber-200 text-amber-700 hover:bg-amber-100 transition-all"
                                    >
                                        <KeyRound size={12} /> Reset PW
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Reset Password Modal */}
            {resetTarget && (
                <div className="fixed inset-0 bg-slate-950/60 backdrop-blur-md flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm border border-slate-200/80 p-6 space-y-4 animate-in zoom-in-95 duration-200">
                        <div className="flex justify-between items-center">
                            <h3 className="font-bold text-slate-800 flex items-center gap-2"><KeyRound size={16} className="text-amber-600" /> Reset Password</h3>
                            <button onClick={() => setResetTarget(null)}><X size={17} className="text-slate-400" /></button>
                        </div>
                        <input
                            type="password"
                            value={newPassword}
                            onChange={e => setNewPassword(e.target.value)}
                            placeholder="รหัสผ่านใหม่..."
                            className="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-amber-400"
                        />
                        <div className="flex gap-2 justify-end">
                            <button onClick={() => setResetTarget(null)} className="px-4 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-100 rounded-xl">ยกเลิก</button>
                            <button onClick={handleResetPassword} disabled={isPending} className="px-4 py-2 text-xs font-bold text-white bg-amber-500 hover:bg-amber-600 rounded-xl flex items-center gap-1.5 disabled:opacity-50">
                                <Save size={14} /> Reset
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Create User Modal */}
            {showCreate && (
                <div className="fixed inset-0 bg-slate-950/60 backdrop-blur-md flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm border border-slate-200/80 animate-in zoom-in-95 duration-200">
                        <div className="flex justify-between items-center px-5 py-4 border-b border-slate-100">
                            <h3 className="font-bold text-slate-800 flex items-center gap-2"><Plus size={16} className="text-emerald-600" /> Create New User</h3>
                            <button onClick={() => setShowCreate(false)}><X size={17} className="text-slate-400" /></button>
                        </div>
                        <div className="p-5 space-y-3">
                            {(["name", "email", "password"] as const).map(field => (
                                <div key={field}>
                                    <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-1.5">{field}</label>
                                    <input
                                        type={field === "password" ? "password" : "text"}
                                        value={createForm[field]}
                                        onChange={e => setCreateForm(f => ({ ...f, [field]: e.target.value }))}
                                        className="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-emerald-400"
                                    />
                                </div>
                            ))}
                            <div>
                                <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-1.5">Role</label>
                                <select
                                    value={createForm.role}
                                    onChange={e => setCreateForm(f => ({ ...f, role: e.target.value }))}
                                    className="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-emerald-400"
                                >
                                    {ROLES.map(r => <option key={r} value={r}>{r}</option>)}
                                </select>
                            </div>
                        </div>
                        <div className="px-5 py-3.5 border-t border-slate-100 flex gap-2 justify-end">
                            <button onClick={() => setShowCreate(false)} className="px-4 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-100 rounded-xl">ยกเลิก</button>
                            <button onClick={handleCreateUser} disabled={isPending} className="px-4 py-2 text-xs font-bold text-white bg-gradient-to-r from-emerald-600 to-green-600 rounded-xl flex items-center gap-1.5 shadow-xs disabled:opacity-50">
                                <Plus size={14} /> Create
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

import { NextRequest } from "next/server";
import { getToken } from "next-auth/jwt";
import { prisma } from "@/lib/prisma";

export async function GET(req: NextRequest) {
    const token = await getToken({ req });
    if (!token?.sub) {
        return new Response("Unauthorized", { status: 401 });
    }
    const userId = token.sub;

    const encoder = new TextEncoder();

    const stream = new ReadableStream({
        async start(controller) {
            let lastSeenTime = new Date(Date.now() - 3000); // 3 seconds before connection start
            let isClosed = false;
            let tickCount = 0;

            const send = (data: object) => {
                if (isClosed) return;
                try {
                    controller.enqueue(encoder.encode(`data: ${JSON.stringify(data)}\n\n`));
                } catch {
                    isClosed = true;
                }
            };

            const sendPing = () => {
                if (isClosed) return;
                try {
                    controller.enqueue(encoder.encode(`: ping\n\n`));
                } catch {
                    isClosed = true;
                }
            };

            // Fast helper to get unread map in a single SQL query
            const fetchUnreadMap = async () => {
                const rows = await prisma.$queryRaw<{ chatRoomId: string; count: number }[]>`
                    SELECT m."chatRoomId", COUNT(*)::int AS count
                    FROM "ChatMessage" m
                    INNER JOIN "ChatMember" cm ON cm."chatRoomId" = m."chatRoomId"
                    WHERE cm."userId" = ${userId}
                      AND m."senderId" != ${userId}
                      AND m."createdAt" > cm."lastReadAt"
                    GROUP BY m."chatRoomId"
                `;
                const map: Record<string, number> = {};
                let total = 0;
                for (const r of rows) {
                    map[r.chatRoomId] = r.count;
                    total += r.count;
                }
                return { map, total };
            };

            // Initial poll: sends complete initial status
            const initialPoll = async () => {
                try {
                    const { map: roomUnreadMap, total: totalUnread } = await fetchUnreadMap();

                    // Fetch latest message per room
                    const memberships = await prisma.chatMember.findMany({
                        where: { userId },
                        select: {
                            chatRoomId: true,
                            chatRoom: {
                                select: {
                                    messages: {
                                        orderBy: { createdAt: "desc" },
                                        take: 1,
                                        select: {
                                            id: true,
                                            body: true,
                                            senderId: true,
                                            createdAt: true,
                                            attachmentUrl: true,
                                            sender: {
                                                select: { name: true },
                                            },
                                        },
                                    },
                                },
                            },
                        },
                    });

                    const roomLatestMessages: Record<string, { id: string, body: string, senderId: string, senderName?: string | null, createdAt: Date }> = {};
                    for (const m of memberships) {
                        if (m.chatRoom?.messages?.length > 0) {
                            const latest = m.chatRoom.messages[0];
                            roomLatestMessages[m.chatRoomId] = {
                                id: latest.id,
                                body: latest.body || (latest.attachmentUrl ? "[ไฟล์แนบ]" : ""),
                                senderId: latest.senderId,
                                senderName: latest.sender?.name,
                                createdAt: latest.createdAt,
                            };
                        }
                    }

                    send({
                        totalUnread,
                        roomUnreadMap,
                        roomLatestMessages,
                        newMessages: [],
                        timestamp: Date.now(),
                    });
                } catch (e) {
                    // Ignore initial error
                }
            };

            // Lightweight delta poll: only runs 1 indexed query when idle
            const deltaPoll = async () => {
                if (isClosed) return;
                tickCount++;

                try {
                    // Query for ANY new messages in rooms the user belongs to since lastSeenTime
                    const newMessages = await prisma.chatMessage.findMany({
                        where: {
                            chatRoom: {
                                members: { some: { userId } }
                            },
                            createdAt: { gt: lastSeenTime }
                        },
                        orderBy: { createdAt: "asc" },
                        select: {
                            id: true,
                            chatRoomId: true,
                            body: true,
                            attachmentUrl: true,
                            attachmentName: true,
                            attachmentType: true,
                            attachmentSize: true,
                            senderId: true,
                            createdAt: true,
                            sender: {
                                select: {
                                    id: true,
                                    name: true,
                                    avatarUrl: true,
                                    email: true,
                                    role: true,
                                }
                            }
                        }
                    });

                    if (newMessages.length > 0) {
                        lastSeenTime = newMessages[newMessages.length - 1].createdAt;

                        // Fetch updated unread counts
                        const { map: roomUnreadMap, total: totalUnread } = await fetchUnreadMap();

                        // Build updated latest message snippet for affected rooms
                        const roomLatestMessages: Record<string, { id: string, body: string, senderId: string, senderName?: string | null, createdAt: Date }> = {};
                        for (const msg of newMessages) {
                            roomLatestMessages[msg.chatRoomId] = {
                                id: msg.id,
                                body: msg.body || (msg.attachmentUrl ? "[ไฟล์แนบ]" : ""),
                                senderId: msg.senderId,
                                senderName: msg.sender.name,
                                createdAt: msg.createdAt,
                            };
                        }

                        send({
                            totalUnread,
                            roomUnreadMap,
                            roomLatestMessages,
                            newMessages,
                            timestamp: Date.now(),
                        });
                    } else if (tickCount % 5 === 0) {
                        // Periodic heartbeat (every ~10-12s) to ensure connection stays active and unread is synced
                        const { map: roomUnreadMap, total: totalUnread } = await fetchUnreadMap();
                        send({
                            totalUnread,
                            roomUnreadMap,
                            newMessages: [],
                            timestamp: Date.now(),
                        });
                    } else {
                        sendPing();
                    }
                } catch {
                    // Transient DB read error, send ping
                    sendPing();
                }
            };

            await initialPoll();

            // Poll every 2.5 seconds with lightweight query
            const interval = setInterval(deltaPoll, 2500);

            // Cleanup when client disconnects
            req.signal.addEventListener("abort", () => {
                isClosed = true;
                clearInterval(interval);
                try {
                    controller.close();
                } catch {
                    // already closed
                }
            });
        },
    });

    return new Response(stream, {
        headers: {
            "Content-Type": "text/event-stream",
            "Cache-Control": "no-cache, no-transform",
            "Connection": "keep-alive",
        },
    });
}

