import { prisma } from "@/lib/prisma";
import { Prisma } from "@prisma/client";
import Link from "next/link";
import { CheckSquare, AlertCircle, TestTube, ListTodo, Calendar, ArrowRight } from "lucide-react";
import TaskCheckbox from "@/components/TaskCheckbox";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth-options";
import DeleteTaskButton from "@/components/DeleteTaskButton";

export default async function MyTasksPage() {
    const session = await getServerSession(authOptions);
    const userId = session?.user?.id;
    const role = session?.user?.role || "USER";

    let taskCondition: Prisma.TaskWhereInput = {};
    if (role === "DEV") {
        taskCondition = { assigneeId: userId };
    } else if (role === "PM") {
        taskCondition = {
            OR: [
                { assigneeId: userId },
                { project: { ownerId: userId } }
            ]
        };
    }

    // Parallel fetch all 4 categories in a single round-trip
    const [tasks, assignedIssues, assignedUATs, assignedReqs] = await Promise.all([
        prisma.task.findMany({
            where: { deletedAt: null, ...taskCondition },
            orderBy: [
                { isCompleted: 'asc' },
                { dueDate: 'asc' }
            ],
            include: {
                project: {
                    select: { id: true, name: true, code: true }
                }
            }
        }),
        prisma.issue.findMany({
            where: { assigneeId: userId, deletedAt: null, status: { notIn: ["Resolved", "Closed"] } },
            include: {
                project: {
                    select: { id: true, name: true, code: true }
                }
            }
        }),
        prisma.uATCase.findMany({
            where: { assigneeId: userId, deletedAt: null, status: { notIn: ["Passed"] } },
            include: {
                project: {
                    select: { id: true, name: true, code: true }
                }
            }
        }),
        prisma.requirement.findMany({
            where: { assigneeId: userId, deletedAt: null, status: { notIn: ["Done"] } },
            include: {
                project: {
                    select: { id: true, name: true, code: true }
                }
            }
        })
    ]);

    const pendingTasks = tasks.filter(t => !t.isCompleted);
    const completedTasks = tasks.filter(t => t.isCompleted);

    return (
        <div className="max-w-5xl mx-auto space-y-7 pb-12">
            {/* Title Banner Header */}
            <div className="bg-white border border-slate-200/80 rounded-3xl shadow-xs p-6 md:p-8 flex items-center gap-4">
                <div className="p-3.5 bg-emerald-50 text-emerald-600 rounded-2xl border border-emerald-100/80 shadow-2xs">
                    <CheckSquare size={28} />
                </div>
                <div>
                    <h1 className="text-2xl font-extrabold text-slate-800 tracking-tight">My Tasks & Work Overview</h1>
                    <p className="text-xs text-slate-500 mt-1">รายการงาน, บั๊ก และหน้าที่ทั้งหมดที่คุณได้รับมอบหมาย</p>
